            r = routes[ri]
            i = 0
            while i < len(r):
                cid = r[i]
                d = demand_of(cid)
                prev = depot_id if i == 0 else r[i - 1]
                nxt = depot_id if i == len(r) - 1 else r[i + 1]
                remove_delta = dist(prev, cid) + dist(cid, nxt) - dist(prev, nxt)
                rj = 0
                while rj < len(routes):
                    if rj != ri:
                        t = routes[rj]
                        if route_load(t) + d <= capacity:
                            pos = 0
                            while pos <= len(t):
                                a = depot_id if pos == 0 else t[pos - 1]
                                b = depot_id if pos == len(t) else t[pos]
                                add_delta = dist(a, cid) + dist(cid, b) - dist(a, b)
                                delta = remove_delta + add_delta
                                if delta < best_delta - 1e-12 or (delta == best_delta and (ri, i, rj, pos, cid) < best_move if best_move is not None else True):
                                    best_delta = delta
                                    best_move = (ri, i, rj, pos)
                                pos += 1
                    rj += 1
                i += 1
            ri += 1
        if best_move is not None:
            ri, i, rj, pos = best_move
            cid = routes[ri].pop(i)
            routes[rj].insert(pos, cid)
            if not routes[ri]:
                routes.pop(ri)
            routes = [two_opt(r) for r in routes]
            improved = True

    # Final cleanup: ensure all customers exactly once
    seen = {}
    for r in routes:
        for cid in r:
            seen[cid] = seen.get(cid, 0) + 1

    missing = []
    for cid in customer_ids:
        if seen.get(cid, 0) == 0:
            missing.append(cid)

    if missing:
        flat = []
        for r in routes:
            for cid in r:
                if seen.get(cid, 0) == 1:
                    flat.append(cid)
        # rebuild deterministically if needed
        order2 = sorted(customer_ids, key=lambda c: (-demand_of(c), c))
        routes = []
        cur = []
        ld = 0
        for cid in order2:
            d = demand_of(cid)
            if cur and ld + d > capacity:
                routes.append(cur)
                cur = [cid]
                ld = d
            else:
                cur.append(cid)
                ld += d
        if cur:
            routes.append(cur)

    return routes
